//! The NIP-TERM extension fixtures: requests and results round-trip, record
//! streams decode whole, fragmented, and out of order, and every invalid
//! case refuses with its stated reason. Runs without the host.
//!
//! `fixtures/nip-term-ext.json` is generated by `build` below and checked
//! byte for byte, so an independent implementation can test against the
//! file alone. After an intended change, regenerate it with
//! `NIP_TERM_FIXTURES=write cargo test -p coder-pty --test ext`.

use base64::Engine as _;
use base64::engine::general_purpose::STANDARD;
use coder_pty::ext::{
    self, Assembler, Axis, Block, BlockPage, BlockPageRead, BlockState, Charset, Charsets, Color,
    Cursor, Features, FinishRecord, History, HistoryRecord, HistorySpan, Keyboard, Layout, Lines,
    Member, MemberState, Modes, Node, Origin, Record, RecordsFrame, Region, Row, RowsRecord, Run,
    ScreenKind, SeqRange, SessionRead, SessionRecord, SessionWrite, Shape, SnapshotJoin,
    StateRecord, StreamKind, Style, Tab, TerminalRecord,
};
use coder_pty::wire::{
    Attach, Body, Frame, Mode, Reason, Size, Status, TerminalRef, TerminalResult, Value,
};
use coder_pty::{Applied, ext::Join};
use serde_json::{Value as Json, json};

const GENERATION: &str = "a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1";
const TERMINAL: &str = "b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2";
const ATTACHMENT: &str = "c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3";
const STREAM: &str = "d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4d4";
const HISTORY_STREAM: &str = "e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5e5";
const SESSION: &str = "f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6f6";
const OTHER: &str = "0909090909090909090909090909090909090909090909090909090909090909";
const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/nip-term-ext.json");

fn request(n: u8) -> String {
    format!("{n:02x}").repeat(32)
}

fn terminal() -> TerminalRef {
    TerminalRef {
        generation: GENERATION.into(),
        terminal: TERMINAL.into(),
    }
}

fn text(text: &str) -> Row {
    Row {
        wrapped: false,
        runs: vec![Run {
            text: text.into(),
            cells: text.len() as u16,
            style: Style::plain(),
        }],
    }
}

fn binding(generation: &str) -> TerminalRecord {
    TerminalRecord {
        format: 1,
        generation: generation.into(),
        terminal: TERMINAL.into(),
        epoch: 1,
        through: 7,
        size: Size::new(3, 20),
        history: HistorySpan { first: 0, count: 5 },
        exit: None,
    }
}

/// A 3-by-20 terminal with five history lines, a prompt, a styled run, a
/// link, and a half-finished CSI sequence in the parser.
fn snapshot_records() -> Vec<Record> {
    let bold = Style {
        fg: Color::Index(2),
        bg: Color::Default,
        flags: 1,
        link: None,
    };
    let linked = Style {
        fg: Color::Rgb([255, 255, 255]),
        bg: Color::Default,
        flags: 8,
        link: Some("https://openagents.com".into()),
    };
    vec![
        Record::Terminal(binding(GENERATION)),
        Record::State(StateRecord {
            alternate: false,
            cursor: Cursor {
                row: 2,
                col: 2,
                pending_wrap: false,
                visible: true,
                shape: Shape::Block,
                blink: false,
            },
            pen: Style::plain(),
            saved_primary: None,
            saved_alternate: None,
            scroll: Region { top: 0, bottom: 2 },
            tabs: vec![8, 16],
            modes: Modes {
                private: vec![7, 25, 2004],
                ansi: vec![],
            },
            charsets: Charsets {
                g0: Charset::Ascii,
                g1: Charset::DecSpecial,
                shift: 0,
            },
            keyboard: Keyboard {
                primary: vec![],
                alternate: vec![],
            },
            title: "make test".into(),
        }),
        Record::Rows(RowsRecord {
            screen: ScreenKind::Primary,
            first: 0,
            rows: vec![
                Row {
                    wrapped: false,
                    runs: vec![
                        Run {
                            text: "ok".into(),
                            cells: 2,
                            style: bold,
                        },
                        Run {
                            text: " docs".into(),
                            cells: 5,
                            style: linked,
                        },
                    ],
                },
                Row {
                    wrapped: false,
                    runs: vec![],
                },
            ],
        }),
        Record::Rows(RowsRecord {
            screen: ScreenKind::Primary,
            first: 2,
            rows: vec![text("$ ")],
        }),
        Record::Continuation(b"\x1b[3".to_vec()),
        Record::Ready,
        Record::History(HistoryRecord {
            first: 2,
            rows: vec![text("line 2"), text("line 3"), text("line 4")],
        }),
        Record::History(HistoryRecord {
            first: 0,
            rows: vec![text("line 0"), text("line 1")],
        }),
        Record::Finish(FinishRecord {
            rows: 5,
            complete: true,
        }),
    ]
}

fn history_records() -> Vec<Record> {
    vec![
        Record::Terminal(binding(GENERATION)),
        Record::History(HistoryRecord {
            first: 0,
            rows: vec![text("line 0"), text("line 1")],
        }),
        Record::Finish(FinishRecord {
            rows: 2,
            complete: true,
        }),
    ]
}

fn record_json(record: &Record) -> Json {
    let name = format!("{:?}", record.tag()).to_uppercase();
    match record {
        Record::Continuation(bytes) => json!({"tag": name, "bytes": STANDARD.encode(bytes)}),
        Record::Ready => json!({"tag": name}),
        other => json!({
            "tag": name,
            "payload": serde_json::from_slice::<Json>(&other.payload()).unwrap(),
        }),
    }
}

fn frames(stream: &str, bytes: &[u8], part_max: usize) -> Vec<RecordsFrame> {
    ext::frames(&terminal(), ATTACHMENT, stream, bytes, part_max)
}

fn to_json<T: serde::Serialize>(value: &T) -> Json {
    serde_json::to_value(value).unwrap()
}

/// A stream whose bytes went through `mutate`, in one part.
fn mutated(records: &[Record], mutate: impl Fn(&mut Vec<u8>)) -> Json {
    let mut bytes = ext::encode_stream(records);
    mutate(&mut bytes);
    to_json(&frames(STREAM, &bytes, ext::PART_MAX))
}

fn invalid_stream(why: &str, kind: &str, reason: &str, frames: Json) -> Json {
    json!({"why": why, "kind": kind, "reason": reason, "frames": frames})
}

fn block(n: u64, command: &str, status: Option<i32>) -> Block {
    Block {
        block: n,
        origin: Origin::Typed,
        command: command.into(),
        command_truncated: false,
        dir: "/home/user/openagents".into(),
        started: Some(1_791_000_000_000 + n * 1000),
        ended: status.map(|_| 1_791_000_000_500 + n * 1000),
        status,
        state: if status.is_some() {
            BlockState::Finished
        } else {
            BlockState::Running
        },
        alternate: false,
        output: Some(SeqRange {
            from: n * 10,
            to: n * 10 + 4,
        }),
        retained: n > 1,
        lines: Some(Lines {
            epoch: 1,
            start: n * 3,
            end: n * 3 + 2,
        }),
    }
}

fn session_record(
    session: Option<String>,
    revision: u64,
    state: Option<MemberState>,
) -> SessionRecord {
    SessionRecord {
        session,
        revision,
        name: "openagents".into(),
        members: vec![
            Member::Terminal {
                member: 1,
                terminal: terminal(),
                state,
            },
            Member::Resource {
                member: 2,
                resource: json!({"kind": "thread", "host": GENERATION, "thread": OTHER}),
            },
        ],
        layout: Layout {
            tabs: vec![Tab {
                name: "work".into(),
                root: Node::Split {
                    axis: Axis::Columns,
                    ratio: 600,
                    first: Box::new(Node::Pane { member: 1 }),
                    second: Box::new(Node::Pane { member: 2 }),
                },
            }],
            active: 0,
        },
    }
}

fn result(n: u8, outcome: Result<Value, Reason>) -> Json {
    to_json(&TerminalResult::from_outcome(
        request(n),
        outcome
            .map(|value| (Status::Accepted, value))
            .map_err(|reason| coder_pty::Refusal::new(reason, "")),
    ))
}

/// The whole fixture file.
fn build() -> Json {
    let snapshot = snapshot_records();
    let bytes = ext::encode_stream(&snapshot);
    let history = history_records();
    let attach =
        Attach::new(request(1), terminal(), Mode::Interact, 0, 65536).joining(Join::Snapshot);
    let block_read = BlockPageRead::new(request(3), terminal(), None, 3);
    let page = BlockPage {
        newest: Some(3),
        oldest: Some(1),
        blocks: vec![
            block(3, "cargo test -p coder-pty", None),
            block(2, "git status", Some(0)),
            block(1, "make", Some(2)),
        ],
        more: false,
    };
    let write = SessionWrite::new(request(5), None, 0, session_record(None, 0, None));

    // The fragmented stream, delivered out of order: parts 1, 0, 3, 2, ...
    let mut fragmented = frames(STREAM, &bytes, 61);
    for pair in fragmented.chunks_mut(2) {
        pair.reverse();
    }

    let records_frame = frames(STREAM, &bytes, ext::PART_MAX).remove(0);
    let mut early = vec![to_json(&records_frame)];
    early.insert(
        0,
        to_json(&Frame::new(
            terminal(),
            ATTACHMENT,
            Body::Output {
                seq: 8,
                data: b"x".to_vec(),
            },
        )),
    );
    // READY ends at the byte after the READY record's header.
    let prefix = ext::encode_stream(&snapshot[..6]).len();
    let timeline = vec![
        to_json(&frames(STREAM, &bytes[..prefix], 8192)[0].clone()),
        to_json(&Frame::new(
            terminal(),
            ATTACHMENT,
            Body::Output {
                seq: 8,
                data: b"1\x1b[0m".to_vec(),
            },
        )),
        {
            let mut rest = frames(STREAM, &bytes[prefix..], 8192).remove(0);
            rest.part = 1;
            to_json(&rest)
        },
        to_json(&Frame::new(
            terminal(),
            ATTACHMENT,
            Body::Output {
                seq: 9,
                data: b"done\r\n".to_vec(),
            },
        )),
    ];
    let mut timeline_first = timeline[0].clone();
    timeline_first["last"] = json!(false);
    let timeline = vec![
        timeline_first,
        timeline[1].clone(),
        timeline[2].clone(),
        timeline[3].clone(),
    ];

    let mut swapped = snapshot.clone();
    swapped.swap(1, 5);
    let mut other_generation = snapshot.clone();
    other_generation[0] = Record::Terminal(binding(OTHER));
    let mut no_finish = snapshot.clone();
    no_finish.pop();
    let mut wrong_finish = snapshot.clone();
    *wrong_finish.last_mut().unwrap() = Record::Finish(FinishRecord {
        rows: 5,
        complete: false,
    });
    let mut conflict = frames(STREAM, &bytes, 61);
    let mut repeat = conflict[0].clone();
    repeat.data[0] ^= 1;
    conflict.insert(1, repeat);
    let mut bad_row = snapshot.clone();
    bad_row[3] = Record::Rows(RowsRecord {
        screen: ScreenKind::Primary,
        first: 2,
        rows: vec![text("\u{1b}]52;c;secret")],
    });
    let mut gap_rows = snapshot.clone();
    gap_rows.remove(3);

    let mut attach_after = to_json(&attach);
    attach_after["after"] = json!(41);
    let mut attach_bare = to_json(&attach);
    attach_bare["requires"] = json!([]);
    let mut record = session_record(None, 0, None);
    record.layout.tabs[0].root = Node::Pane { member: 9 };
    let no_member = to_json(&SessionWrite::new(request(5), None, 0, record));
    let mut record = session_record(None, 0, None);
    record.layout.tabs[0].root = Node::Split {
        axis: Axis::Rows,
        ratio: 500,
        first: Box::new(Node::Pane { member: 1 }),
        second: Box::new(Node::Pane { member: 1 }),
    };
    let two_panes = to_json(&SessionWrite::new(request(5), None, 0, record));
    let length_past_bound = mutated(&snapshot, |b| {
        b[2..6].copy_from_slice(&((ext::PAYLOAD_MAX as u32) + 1).to_le_bytes());
    });
    let length_past_end = mutated(&snapshot, |b| {
        b.pop();
    });
    let unknown_tag = mutated(&snapshot, |b| b[0..2].copy_from_slice(&99u16.to_le_bytes()));

    json!({
        "description": "NIP-TERM extension fixtures. Generated by crates/coder-pty/tests/ext.rs; regenerate rather than edit.",
        "terminal": to_json(&terminal()),
        "attachment": ATTACHMENT,
        "requests": {
            "attach_snapshot": to_json(&attach),
            "attach_replay": to_json(&Attach::new(request(2), terminal(), Mode::Observe, 41, 65536).joining(Join::Replay)),
            "history": to_json(&History::new(request(3), terminal(), ATTACHMENT, 1, 2, 2)),
            "block_page": to_json(&block_read),
            "session_read": to_json(&SessionRead::new(request(4), SESSION)),
            "session_write": to_json(&write),
        },
        "results": {
            "history_stream": result(3, Ok(Value::Stream { stream: HISTORY_STREAM.into() })),
            "blocks": result(3, Ok(Value::Blocks { page })),
            "session": result(4, Ok(Value::Session { record: session_record(Some(SESSION.into()), 4, Some(MemberState::Lost)) })),
            "history_unavailable": result(3, Err(Reason::ContentUnavailable)),
            "history_stale": result(3, Err(Reason::Stale)),
            "session_stale": result(5, Err(Reason::Stale)),
            "snapshot_unsupported": result(1, Err(Reason::UnsupportedFeature)),
        },
        "streams": {
            "snapshot": {
                "records": snapshot.iter().map(record_json).collect::<Vec<_>>(),
                "bytes": STANDARD.encode(&bytes),
                "one_part": to_json(&frames(STREAM, &bytes, ext::PART_MAX)),
                "fragmented": to_json(&fragmented),
            },
            "history": {
                "read": {"epoch": 1, "before": 2, "rows": 2},
                "records": history.iter().map(record_json).collect::<Vec<_>>(),
                "frames": to_json(&frames(HISTORY_STREAM, &ext::encode_stream(&history), ext::PART_MAX)),
            },
        },
        "invalid_streams": [
            invalid_stream("a payload byte changed after its checksum", "snapshot", "malformed",
                mutated(&snapshot, |b| b[12] ^= 0x20)),
            invalid_stream("a length above 1 MiB", "snapshot", "malformed",
                length_past_bound),
            invalid_stream("the final record's length runs past the end", "snapshot", "malformed",
                length_past_end),
            invalid_stream("an unknown tag", "snapshot", "malformed",
                unknown_tag),
            invalid_stream("READY before STATE", "snapshot", "malformed",
                to_json(&frames(STREAM, &ext::encode_stream(&swapped), ext::PART_MAX))),
            invalid_stream("TERMINAL binds another host generation", "snapshot", "identity_mismatch",
                to_json(&frames(STREAM, &ext::encode_stream(&other_generation), ext::PART_MAX))),
            invalid_stream("the last part arrives without FINISH", "snapshot", "malformed",
                to_json(&frames(STREAM, &ext::encode_stream(&no_finish), ext::PART_MAX))),
            invalid_stream("FINISH says incomplete after reaching the oldest line", "snapshot", "malformed",
                to_json(&frames(STREAM, &ext::encode_stream(&wrong_finish), ext::PART_MAX))),
            invalid_stream("a part repeated with different bytes", "snapshot", "malformed",
                to_json(&conflict)),
            invalid_stream("a row carries a control character", "snapshot", "malformed",
                to_json(&frames(STREAM, &ext::encode_stream(&bad_row), ext::PART_MAX))),
            invalid_stream("the primary screen's last row is missing", "snapshot", "malformed",
                to_json(&frames(STREAM, &ext::encode_stream(&gap_rows), ext::PART_MAX))),
            invalid_stream("a history stream for epoch 1 read as epoch 2", "history_epoch_2", "stale",
                to_json(&frames(HISTORY_STREAM, &ext::encode_stream(&history), ext::PART_MAX))),
        ],
        "invalid_requests": [
            {"why": "a base-profile host sees a feature", "schema": "attach_base",
             "reason": "unsupported_feature", "body": to_json(&attach)},
            {"why": "a snapshot join that also asks to replay after 41", "schema": "attach",
             "reason": "malformed", "body": attach_after},
            {"why": "join without the snapshot feature", "schema": "attach", "reason": "malformed",
             "body": attach_bare},
            {"why": "a history read of 2001 rows", "schema": "history", "reason": "malformed",
             "body": to_json(&History::new(request(3), terminal(), ATTACHMENT, 1, 2, 2001))},
            {"why": "a history read to a host without snapshots", "schema": "history_base",
             "reason": "unsupported_feature", "body": to_json(&History::new(request(3), terminal(), ATTACHMENT, 1, 2, 2))},
            {"why": "a block page of 33", "schema": "block_page", "reason": "malformed",
             "body": to_json(&BlockPageRead::new(request(3), terminal(), Some(9), 33))},
            {"why": "a session write that sets a member's state", "schema": "session_write", "reason": "malformed",
             "body": to_json(&SessionWrite::new(request(5), None, 0, session_record(None, 0, Some(MemberState::Live))))},
            {"why": "a pane that names no member", "schema": "session_write", "reason": "malformed",
             "body": no_member},
            {"why": "one member in two panes", "schema": "session_write", "reason": "malformed",
             "body": two_panes},
            {"why": "a write to a session without its base revision", "schema": "session_write", "reason": "malformed",
             "body": to_json(&SessionWrite::new(request(5), Some(SESSION.into()), 0, session_record(Some(SESSION.into()), 0, None)))},
        ],
        "history_admission": [
            {"why": "rows within retention", "host": {"epoch": 1, "history": {"first": 0, "count": 5}},
             "read": {"epoch": 1, "before": 4, "rows": 10}, "sends": 4},
            {"why": "rows that left retention", "host": {"epoch": 1, "history": {"first": 100, "count": 50}},
             "read": {"epoch": 1, "before": 90, "rows": 10}, "reason": "content_unavailable"},
            {"why": "the line epoch changed", "host": {"epoch": 2, "history": {"first": 0, "count": 5}},
             "read": {"epoch": 1, "before": 4, "rows": 10}, "reason": "stale"},
            {"why": "before past the newest history line", "host": {"epoch": 1, "history": {"first": 0, "count": 5}},
             "read": {"epoch": 1, "before": 6, "rows": 10}, "reason": "malformed"},
        ],
        "join": {
            "early": early,
            "timeline": timeline,
        },
    })
}

fn fixtures() -> Json {
    let text = std::fs::read_to_string(PATH).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn parse<T: serde::de::DeserializeOwned>(json: &Json) -> T {
    serde_json::from_value(json.clone()).unwrap()
}

fn round_trip<T: serde::de::DeserializeOwned + serde::Serialize>(json: &Json) -> T {
    let value: T = parse(json);
    assert_eq!(&to_json(&value), json);
    value
}

fn assemble(kind: StreamKind, frames: &Json) -> Result<(Assembler, Vec<Record>), Reason> {
    let mut assembler = Assembler::new(kind, terminal());
    let mut records = Vec::new();
    for frame in frames.as_array().unwrap() {
        let frame: RecordsFrame = parse(frame);
        records.extend(assembler.push(&frame).map_err(|r| r.reason)?);
    }
    Ok((assembler, records))
}

#[test]
fn the_fixture_file_is_current() {
    if std::env::var_os("NIP_TERM_FIXTURES").is_some_and(|v| v == "write") {
        let mut text = serde_json::to_string_pretty(&build()).unwrap();
        text.push('\n');
        std::fs::write(PATH, text).unwrap();
    }
    assert_eq!(
        fixtures(),
        build(),
        "regenerate with NIP_TERM_FIXTURES=write"
    );
}

#[test]
fn every_request_and_result_round_trips_and_checks() {
    let all = fixtures();
    let requests = &all["requests"];
    round_trip::<Attach>(&requests["attach_snapshot"])
        .check_with(Features::ALL)
        .unwrap();
    round_trip::<Attach>(&requests["attach_replay"])
        .check_with(Features::ALL)
        .unwrap();
    round_trip::<History>(&requests["history"]).check().unwrap();
    let read = round_trip::<BlockPageRead>(&requests["block_page"]);
    read.check().unwrap();
    round_trip::<SessionRead>(&requests["session_read"])
        .check()
        .unwrap();
    round_trip::<SessionWrite>(&requests["session_write"])
        .check()
        .unwrap();
    for (name, json) in all["results"].as_object().unwrap() {
        let result = round_trip::<TerminalResult>(json);
        match (name.as_str(), result.value) {
            ("blocks", Some(Value::Blocks { page })) => {
                page.check(&read).unwrap();
                assert!(page.fits());
            }
            ("session", Some(Value::Session { record })) => {
                record.check().unwrap();
                assert_eq!(record.members[0].state(), Some(MemberState::Lost));
            }
            ("history_stream", Some(Value::Stream { stream })) => {
                assert_eq!(stream, HISTORY_STREAM)
            }
            (_, None) => assert_eq!(result.status, Status::Refused),
            (other, value) => panic!("unexpected {other}: {value:?}"),
        }
    }
}

#[test]
fn a_complete_snapshot_decodes_to_its_records() {
    let all = fixtures();
    let snapshot = &all["streams"]["snapshot"];
    let (assembler, records) = assemble(StreamKind::Snapshot, &snapshot["one_part"]).unwrap();
    assert!(assembler.finished());
    assert_eq!(assembler.ready().unwrap().through, 7);
    assert_eq!(records, snapshot_records());
    let listed: Vec<Json> = records.iter().map(record_json).collect();
    assert_eq!(&Json::from(listed), &snapshot["records"]);
    let bytes = STANDARD
        .decode(snapshot["bytes"].as_str().unwrap())
        .unwrap();
    assert_eq!(bytes, ext::encode_stream(&records));
}

#[test]
fn a_fragmented_snapshot_out_of_order_decodes_the_same() {
    let all = fixtures();
    let snapshot = &all["streams"]["snapshot"];
    let parts = snapshot["fragmented"].as_array().unwrap();
    assert!(parts.len() > 8, "records span parts");
    assert_ne!(parts[0]["part"], 0, "delivered out of order");
    let (assembler, records) = assemble(StreamKind::Snapshot, &snapshot["fragmented"]).unwrap();
    assert!(assembler.finished());
    assert_eq!(records, snapshot_records());
}

#[test]
fn a_history_stream_decodes_within_its_read() {
    let all = fixtures();
    let history = &all["streams"]["history"];
    let kind = StreamKind::History {
        epoch: 1,
        before: 2,
        rows: 2,
    };
    let (assembler, records) = assemble(kind, &history["frames"]).unwrap();
    assert!(assembler.finished());
    assert_eq!(records, history_records());
}

#[test]
fn every_invalid_stream_refuses_with_its_reason() {
    let all = fixtures();
    for case in all["invalid_streams"].as_array().unwrap() {
        let kind = match case["kind"].as_str().unwrap() {
            "snapshot" => StreamKind::Snapshot,
            "history_epoch_2" => StreamKind::History {
                epoch: 2,
                before: 2,
                rows: 2,
            },
            other => panic!("no kind {other}"),
        };
        let reason = assemble(kind, &case["frames"]).err();
        assert_eq!(
            reason.map(Reason::code),
            case["reason"].as_str(),
            "{}",
            case["why"]
        );
    }
}

#[test]
fn every_invalid_request_refuses_with_its_reason() {
    let all = fixtures();
    for case in all["invalid_requests"].as_array().unwrap() {
        let body = &case["body"];
        let refusal = match case["schema"].as_str().unwrap() {
            "attach_base" => parse::<Attach>(body).check(),
            "attach" => parse::<Attach>(body).check_with(Features::ALL),
            "history" => parse::<History>(body).check(),
            "history_base" => parse::<History>(body).check_with(Features::NONE),
            "block_page" => parse::<BlockPageRead>(body).check(),
            "session_write" => parse::<SessionWrite>(body).check(),
            other => panic!("no schema {other}"),
        }
        .unwrap_err();
        assert_eq!(
            refusal.reason.code(),
            case["reason"].as_str().unwrap(),
            "{}",
            case["why"]
        );
    }
}

#[test]
fn history_admission_answers_retention_and_epochs() {
    let all = fixtures();
    for case in all["history_admission"].as_array().unwrap() {
        let read = &case["read"];
        let history = History::new(
            request(3),
            terminal(),
            ATTACHMENT,
            read["epoch"].as_u64().unwrap(),
            read["before"].as_u64().unwrap(),
            read["rows"].as_u64().unwrap(),
        );
        let span: HistorySpan = parse(&case["host"]["history"]);
        let outcome = history.admit(case["host"]["epoch"].as_u64().unwrap(), span);
        match case["reason"].as_str() {
            Some(reason) => assert_eq!(
                outcome.unwrap_err().reason.code(),
                reason,
                "{}",
                case["why"]
            ),
            None => assert_eq!(outcome.unwrap(), case["sends"].as_u64().unwrap()),
        }
    }
}

#[test]
fn a_base_profile_peer_never_accepts_an_extension_body() {
    let all = fixtures();
    // A replay-only client's frame parser refuses a records frame.
    let records = &all["streams"]["snapshot"]["one_part"][0];
    assert!(serde_json::from_value::<Frame>(records.clone()).is_err());
    // A base-profile host refuses the snapshot attach truthfully.
    let attach: Attach = parse(&all["requests"]["attach_snapshot"]);
    assert_eq!(
        attach.check().unwrap_err().reason,
        Reason::UnsupportedFeature
    );
    // A plain attach serializes exactly as before: no join field.
    let plain = to_json(&Attach::new(request(1), terminal(), Mode::Interact, 0, 1));
    assert!(plain.get("join").is_none());
    assert!(Features::advertised::<&str>(&[]) == Features::NONE);
}

#[test]
fn a_sequenced_frame_before_ready_is_refused() {
    let all = fixtures();
    let early = all["join"]["early"].as_array().unwrap();
    let mut join = SnapshotJoin::new(terminal(), 100, 20);
    let refusal = join.frame(&parse(&early[0])).unwrap_err();
    assert_eq!(refusal.reason, Reason::Malformed);
}

#[test]
fn live_frames_after_ready_continue_from_through() {
    let all = fixtures();
    let timeline = all["join"]["timeline"].as_array().unwrap();
    let mut join = SnapshotJoin::new(terminal(), 100, 20);
    let first = join.records(&parse(&timeline[0])).unwrap();
    assert_eq!(first.last(), Some(&Record::Ready));
    assert_eq!(join.state().resume_after(), 7);
    assert!(matches!(
        join.frame(&parse(&timeline[1])).unwrap(),
        Applied::Output { seq: 8, .. }
    ));
    let rest = join.records(&parse(&timeline[2])).unwrap();
    assert!(matches!(rest.last(), Some(Record::Finish(_))));
    assert!(join.assembler().finished());
    assert!(matches!(
        join.frame(&parse(&timeline[3])).unwrap(),
        Applied::Output { seq: 9, .. }
    ));
    assert_eq!(join.state().resume_after(), 9);
}

#[test]
fn a_host_trims_a_block_page_to_the_result_bound() {
    let long = "x".repeat(ext::BLOCK_TEXT_MAX);
    let mut page = BlockPage {
        newest: Some(40),
        oldest: Some(1),
        blocks: (9..=40)
            .rev()
            .map(|n| Block {
                command: long.clone(),
                dir: long.clone(),
                ..block(n, "", Some(0))
            })
            .collect(),
        more: true,
    };
    assert!(!page.fits());
    while !page.fits() {
        page.blocks.pop();
    }
    let read = BlockPageRead::new(request(3), terminal(), None, 32);
    page.check(&read).unwrap();
    assert!(page.blocks.len() < 32);
}
